#include <gtest/gtest.h>

#include "bench/report.hpp"

TEST(MissingFacts, CountsAFactWithAnEmptyValueAsAbsent) {
  const bench::RunRecord record{.case_name = "normal",
                                .environment = {{.name = "commit", .value = "6d7552c"},
                                                {.name = "image digest", .value = ""}}};
  const std::vector<std::string> missing = bench::missing_facts(record);
  EXPECT_NE(std::ranges::find(missing, "image digest"), missing.end());
  EXPECT_EQ(std::ranges::find(missing, "commit"), missing.end());
}

#include <algorithm>
#include <array>
#include <format>
#include <iostream>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace bench {

// bench/report.hpp: one run turned into something another engineer can act on.

// One fact about the run: a name and whatever the shell managed to find out.
struct Fact {
  std::string name;
  std::string value;
};

// Everything the report holds besides the verdict itself.
struct RunRecord {
  std::string case_name;
  std::vector<Fact> inputs;       // what was asked for: scenario, arguments, parameters, seed
  std::vector<Fact> environment;  // where it ran: commit, image, versions, middleware
  std::vector<Fact> timing;       // how long it took, on both clocks
};

// The facts a run has to record before two runs can be compared. The reproducibility topic named
// them; keeping the list here means a report cannot quietly leave one out.
[[nodiscard]] std::vector<std::string> missing_facts(const RunRecord& record) {
  constexpr std::array<std::string_view, 6> required{"commit",       "image digest", "gazebo",
                                                     "rmw",          "seed",         "real-time factor"};
  std::vector<std::string> missing;
  for (const std::string_view name : required) {
    const auto present = [name](const Fact& fact) { return fact.name == name && !fact.value.empty(); };
    if (!std::ranges::any_of(record.inputs, present) && !std::ranges::any_of(record.environment, present) &&
        !std::ranges::any_of(record.timing, present)) {
      missing.emplace_back(name);
    }
  }
  return missing;
}

namespace {

[[nodiscard]] std::string table(std::string_view title, std::span<const Fact> facts) {
  std::string text = std::format("\n## {}\n\n| | |\n|---|---|\n", title);
  for (const Fact& fact : facts) {
    text += std::format("| {} | {} |\n", fact.name, fact.value.empty() ? "not recorded" : fact.value);
  }
  return text;
}

[[nodiscard]] std::string_view first_line(std::string_view text) {
  const auto end = text.find('\n');
  return end == std::string_view::npos ? text : text.substr(0, end);
}

}  // namespace

// The report, as Markdown, for a person who was not there when the run happened.
[[nodiscard]] std::string report(const RunRecord& record, std::string_view verdict) {
  const std::string_view outcome = first_line(verdict);
  std::string text = std::format("# {}: {}\n", record.case_name, outcome.empty() ? "no verdict" : outcome);
  text += table("Inputs", record.inputs);
  text += table("Environment", record.environment);
  text += table("Timing", record.timing);
  text += "\n## Result\n\n";  // indented, so the verdict needs no fence inside a Markdown file
  for (const auto part : std::views::split(verdict, '\n')) {
    const std::string_view verdict_line(part.begin(), part.end());
    if (!verdict_line.empty()) text += std::format("    {}\n", verdict_line);
  }

  const std::vector<std::string> missing = missing_facts(record);
  if (!missing.empty()) {
    text += "\n## Not recorded\n\n";
    for (const std::string& name : missing) text += std::format("- {}\n", name);
    text += "\nA run missing any of these can be read, and cannot be compared with another.\n";
  }
  return text;
}

}  // namespace bench

int main() {
  const bench::RunRecord record{
      .case_name = "normal_no_relay",
      .inputs = {{.name = "scenario", .value = "normal"},
                 {.name = "launch arguments", .value = "relay:=False"},
                 {.name = "parameter file", .value = "config/normal.yaml, sha256 9f2c1a…"},
                 {.name = "seed", .value = ""}},
      .environment = {{.name = "commit", .value = "6d7552c"},
                      {.name = "image digest", .value = ""},
                      {.name = "os", .value = "Ubuntu 24.04"},
                      {.name = "gazebo", .value = "Gazebo Sim 8.9.0"},
                      {.name = "rmw", .value = "rmw_fastrtps_cpp"}},
      .timing = {{.name = "wall seconds", .value = "46.2"},
                 {.name = "simulated seconds", .value = "29.0"},
                 {.name = "real-time factor", .value = "0.94"}}};

  constexpr std::string_view verdict =
      "fail\nscenario: normal\nsamples: 790\n"
      "failed goals reached in order: 0.00, at least 2.00\n"
      "ok     top speed: 0.00 m/s, at most 0.30 m/s\n";

  std::cout << bench::report(record, verdict);
}

// One line of the facts file: [inputs], [environment], [timing], or "name: value" under one.
std::vector<bench::Fact>* group = &record.inputs;
for (std::string line; std::getline(in, line);) {
  if (line == "[inputs]") group = &record.inputs;
  else if (line == "[environment]") group = &record.environment;
  else if (line == "[timing]") group = &record.timing;
  else if (const auto colon = line.find(": "); colon != std::string::npos) {
    group->push_back({.name = line.substr(0, colon), .value = line.substr(colon + 2)});
  }
}

// In finish(), after the verdict is written. Only this node sees the simulation clock, so it
// records the run's simulated length and the shell divides by its own measurement.
if (!facts_file_.empty() && elapsed) {
  std::ofstream facts(facts_file_, std::ios::app);
  facts << std::format("[timing]\nsimulated seconds: {:.2f}\n",
                       std::chrono::duration<double>(*elapsed).count());
}
